  const createdMs = now();
  const createdAt = new Date(createdMs).toISOString();
  const deadlineMs = boundedPositiveMs(args.deadlineMs, MANAGED_HOST_RUN_DEFAULT_DEADLINE_MS, MANAGED_HOST_RUN_MAX_DEADLINE_MS);","stderr":"","interrupted":false,"isImage":false,"noOutputExpected":false}}

