    environment.LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY === undefined
      ? false
      : sha256(environment.LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY) === owner.capabilityDigest
        && environment.LATTICE_AGENT === spec.agentType
  );
